1: <html>
2:   <head>
3:     <title>Flask + Celery Examples</title>
4:     <style>
5:         .progress {
6:             width: 100%;
7:             text-align: center;
8:         }
9:     </style>
10:   </head>
11:   <body>
12:     <h1>Flask + Celery Examples</h1>
13:     <h2>Example 1: Send Asynchronous Email</h2>
14:     {% for message in get_flashed_messages() %}
15:     <p style="color: red;">{{ message }}</p>
16:     {% endfor %}
17:     <form method="POST">
18:       <p>Send test email to: <input type="text" name="email" value="{{ email }}"></p>
19:       <input type="submit" name="submit" value="Send">
20:       <input type="submit" name="submit" value="Send in 1 minute">
21:     </form>
22:     <hr>
23:     <h2>Example 2: Long running task with progress updates</h2>
24:     <!--<button onclick="start_long_task();">Start Long Calculation</button><br><br>-->
25:     <button id="start-bg-job">Start Long Calculation</button><br><br>
26:     <div id="progress"></div>
27: 
28:     <script src="//cdnjs.cloudflare.com/ajax/libs/nanobar/0.2.1/nanobar.min.js"></script>
29:     <script src="//cdnjs.cloudflare.com/ajax/libs/jquery/2.1.3/jquery.min.js"></script>
30:     <script>
31:         function start_long_task() {
32:             // add task status elements
33:             div = $('<div class="progress"><div></div><div>0%</div><div>...</div><div>&nbsp;</div></div><hr>');
34:             $('#progress').append(div);
35: 
36:             // create a progress bar
37:             var nanobar = new Nanobar({
38:                 bg: '#44f',
39:                 target: div[0].childNodes[0]
40:             });
41: 
42:             // send ajax POST request to start background job
43:             $.ajax({
44:                 type: 'POST',
45:                 url: '/longtask',
46:                 success: function(data, status, request) {
47:                     status_url = request.getResponseHeader('Location');
48:                     update_progress(status_url, nanobar, div[0]);
49:                 },
50:                 error: function() {
51:                     alert('Unexpected error');
52:                 }
53:             });
54:         }
55:         function update_progress(status_url, nanobar, status_div) {
56:             // send GET request to status URL
57:             $.getJSON(status_url, function(data) {
58:                 // update UI
59:                 percent = parseInt(data['current'] * 100 / data['total']);
60:                 nanobar.go(percent);
61:                 $(status_div.childNodes[1]).text(percent + '%');
62:                 $(status_div.childNodes[2]).text(data['status']);
63:                 if (data['state'] != 'PENDING' && data['state'] != 'PROGRESS') {
64:                     if ('result' in data) {
65:                         // show result
66:                         $(status_div.childNodes[3]).text('Result: ' + data['result']);
67:                     }
68:                     else {
69:                         // something unexpected happened
70:                         $(status_div.childNodes[3]).text('Result: ' + data['state']);
71:                     }
72:                 }
73:                 else {
74:                     // rerun in 2 seconds
75:                     setTimeout(function() {
76:                         update_progress(status_url, nanobar, status_div);
77:                     }, 2000);
78:                 }
79:             });
80:         }
81:         $(function() {
82:             $('#start-bg-job').click(start_long_task);
83:         });
84:     </script>
85:   </body>
86: </html>
